<style>
.hero { position:relative; z-index:10; min-height:82vh; display:flex; flex-direction:column; justify-content:center; padding:48px 60px; margin-top:-30px; overflow:hidden; }
.hero-inner { display:flex; align-items:center; gap:60px; width:100%; }
.hero-left { flex:1; min-width:0; }
.hero-glitch-text { font-family:'Press Start 2P',sans-serif; font-size:clamp(1.8rem,4.5vw,3.4rem); line-height:.9; letter-spacing:.02em; display:inline-block; max-width:600px; animation:heroIn 1s ease both; }
@keyframes heroIn { from{opacity:0;transform:translateY(40px) skewX(-5deg)} to{opacity:1;transform:none} }
.line1 { display:block; color:transparent; -webkit-text-stroke:2px var(--gold); }
.line2 { display:block; color:var(--neon-pink); animation:glitch 4s infinite; margin-top:10px; }
@keyframes glitch { 0%,90%,100%{transform:none;clip-path:none} 92%{transform:translateX(-3px);clip-path:polygon(0 20%,100% 20%,100% 40%,0 40%)} 94%{transform:translateX(3px);clip-path:polygon(0 60%,100% 60%,100% 80%,0 80%)} 96%{transform:none;clip-path:none} }
.line3 { display:block; color:var(--neon-yellow); margin-top:10px; }
.hero-sub { display:flex; flex-direction:column; gap:4px; margin-top:26px; max-width:620px; padding-left:22px; animation:heroIn 1s .3s ease both; }
.hero-flag { font-family:'VT323',monospace; font-size:2rem; letter-spacing:.08em; color:var(--gold); line-height:1.2; }
.hero-line { font-family:'VT323',monospace; font-size:1.55rem; letter-spacing:.08em; color:rgba(245,205,210,0.8); line-height:1.5; }
.hero-actions { display:flex; gap:20px; margin-top:32px; animation:heroIn 1s .5s ease both; align-items:center; flex-wrap:wrap; }
.hero-anim { flex:0 0 min(460px,42%); display:flex; align-items:center; justify-content:center; animation:heroIn 1s .2s ease both; }
.scene { position:relative; width:100%; aspect-ratio:736/618; background:#180B1B; border:1px solid rgba(232,93,130,0.35); border-radius:10px; overflow:hidden; }
.code { position:absolute; top:5%; bottom:17%; left:2.5%; width:44%; display:flex; flex-direction:column; justify-content:space-between; }
.ln { display:flex; gap:10px; align-items:center; height:7px; clip-path:inset(0 100% 0 0); animation:typeIn 10s steps(16) infinite; animation-delay:var(--d); }
